import ast
import hashlib
import json
import random
import warnings
from collections import Counter
from dataclasses import asdict
from pathlib import Path

import numpy as np
import pyarrow.parquet as pq
from tokenizers import Tokenizer

from pycoder.config import FilterConfig

AUTOGENERATED_MARKERS = ("auto-generated", "autogenerated", "automatically generated",
                         "generated by", "do not edit")


def rejection_reason(content: str | None, config: FilterConfig) -> str | None:
    """Return why a document fails the basic quality filter, or None to keep it."""
    if content is None:
        return "unreadable"
    size = len(content.encode())
    if size < config.min_bytes:
        return "too_small"
    if size > config.max_bytes:
        return "too_large"
    lengths = [len(line) for line in content.splitlines()]
    if not lengths:
        return "too_small"
    if max(lengths) > config.max_line_length:
        return "long_line"
    if sum(lengths) / len(lengths) > config.max_mean_line_length:
        return "long_mean_line"
    if sum(c.isalnum() for c in content) / len(content) < config.min_alnum_fraction:
        return "low_alnum"
    if config.skip_autogenerated:
        header = "\n".join(content.splitlines()[:5]).lower()
        if any(marker in header for marker in AUTOGENERATED_MARKERS):
            return "autogenerated"
    if config.check_syntax:
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                ast.parse(content)
        except (SyntaxError, ValueError, RecursionError, MemoryError):
            return "syntax_error"
    return None


def read_documents(source: str, text_column: str = "text"):
    """Yield (identifier, content) from .py files and parquet rows under source.

    Content is None when a file is not valid UTF-8 or a parquet value is null. A leading
    byte-order mark is removed.
    """
    root = Path(source)
    if root.is_file():
        py_files, parquet_files = ([], [root]) if root.suffix == ".parquet" else ([root], [])
    else:
        py_files, parquet_files = sorted(root.rglob("*.py")), sorted(root.rglob("*.parquet"))
    for path in py_files:
        try:
            yield str(path), path.read_bytes().decode("utf-8-sig")
        except UnicodeDecodeError:
            yield str(path), None
    for path in parquet_files:
        file = pq.ParquetFile(path)
        names = file.schema_arrow.names
        if text_column not in names:
            raise ValueError(f"{path} has no {text_column!r} column")
        columns = [text_column, *(c for c in ("repo_name", "path") if c in names)]
        index = 0
        for batch in file.iter_batches(batch_size=1024, columns=columns):
            for row in batch.to_pylist():
                text = row[text_column]
                yield (f"{row['repo_name']}/{row['path']}" if len(columns) == 3
                       else f"{path}#{index}"), text and text.removeprefix("﻿")
                index += 1


def split_files(source: str, validation_fraction: float = 0.2, seed: int = 42,
                text_column: str = "text", filters: FilterConfig | None = None):
    """Filter, deduplicate and split documents; return (train, val, rejection counts).

    With filters=None only unreadable documents are dropped.
    """
    if not 0 < validation_fraction < 1:
        raise ValueError("validation_fraction must be between 0 and 1")
    unique, rejected = {}, Counter()
    for path, content in read_documents(source, text_column):
        reason = "unreadable" if content is None else None
        if filters is not None:
            reason = rejection_reason(content, filters)
        if reason:
            rejected[reason] += 1
            continue
        digest = hashlib.sha256(content.encode()).hexdigest()
        if digest in unique:
            rejected["duplicate"] += 1
        unique.setdefault(digest, (path, content))
    items = list(unique.values())
    if len(items) < 2:
        raise ValueError("At least two distinct Python files are required")
    random.Random(seed).shuffle(items)
    n_val = min(len(items) - 1, max(1, round(len(items) * validation_fraction)))
    return items[n_val:], items[:n_val], dict(rejected)


def prepare(source: str, tokenizer_path: str, output: str, validation_fraction: float = 0.2,
            seed: int = 42, text_column: str = "text", filters: FilterConfig | None = None):
    train_items, val_items, rejected = split_files(source, validation_fraction, seed,
                                                   text_column, filters)
    tok = Tokenizer.from_file(tokenizer_path)
    bos, eos = tok.token_to_id("<|bos|>"), tok.token_to_id("<|eos|>")
    if bos is None or eos is None:
        raise ValueError("Tokenizer must contain BOS and EOS")
    dest = Path(output)
    dest.mkdir(parents=True, exist_ok=True)
    manifest = {"filters": asdict(filters) if filters else None, "rejected": rejected}
    for split, examples in (("train", train_items), ("val", val_items)):
        ids = []
        for _, content in examples:
            ids.extend([bos, *tok.encode(content).ids, eos])
        np.asarray(ids, dtype=np.uint32).tofile(dest / f"{split}.bin")
        manifest[split] = [str(path) for path, _ in examples]
    (dest / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    return manifest
